CREATE OR REPLACE FUNCTION public.apply_claim_decision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE assigned_officer uuid; claim_status claim_state;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM app_users WHERE id=NEW.officer_id AND role='officer' AND is_active) THEN
  RAISE EXCEPTION 'Decision requires an active officer';
 END IF;
 SELECT officer_id INTO assigned_officer FROM claim_assignments WHERE claim_id=NEW.claim_id;
 SELECT status INTO claim_status FROM warranty_claims WHERE id=NEW.claim_id FOR UPDATE;
 IF assigned_officer IS DISTINCT FROM NEW.officer_id OR claim_status <> 'in_review' THEN
  RAISE EXCEPTION 'Only the assigned officer may decide an in-review claim';
 END IF;
 UPDATE warranty_claims SET status=NEW.verdict::text::claim_state,updated_at=now() WHERE id=NEW.claim_id;
 IF NEW.verdict='approved' THEN
  INSERT INTO repair_orders(claim_id,notes)
  VALUES(NEW.claim_id,'Created automatically following approval');
 END IF;
 INSERT INTO audit_events(event_type,entity_id,actor_id,details)
 VALUES('claim_decision',NEW.claim_id,NEW.officer_id,
   jsonb_build_object('verdict',NEW.verdict,'reason',NEW.reason));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.audit_repair_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_actor uuid;
BEGIN
 SELECT officer_id INTO v_actor FROM claim_assignments WHERE claim_id=NEW.claim_id;
 INSERT INTO audit_events(event_type,entity_id,actor_id,details)
 VALUES('repair_status_changed',NEW.claim_id,v_actor,
 jsonb_build_object('from',OLD.status,'to',NEW.status));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_assignment_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_status claim_state;
BEGIN
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'Claim assignment is immutable';
 END IF;
 SELECT status INTO v_status FROM warranty_claims WHERE id = NEW.claim_id FOR UPDATE;
 IF v_status IS DISTINCT FROM 'submitted' THEN
  RAISE EXCEPTION 'Only submitted claims may be assigned';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM app_users WHERE id=NEW.officer_id AND role='officer' AND is_active) THEN
  RAISE EXCEPTION 'Assigned user is not an active officer';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_claim_state_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'INSERT' THEN
  IF NEW.status <> 'submitted' THEN
   RAISE EXCEPTION 'New claims must begin in submitted state';
  END IF;
  RETURN NEW;
 END IF;

 -- Identity and issue description are historical claim facts, not editable
 -- after submission. An officer decision is instead recorded in a new row.
 IF NEW.warranty_id IS DISTINCT FROM OLD.warranty_id OR
    NEW.customer_id IS DISTINCT FROM OLD.customer_id OR
    NEW.issue_description IS DISTINCT FROM OLD.issue_description OR
    NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN
  RAISE EXCEPTION 'Submitted claim facts cannot be rewritten';
 END IF;

 IF NEW.status = OLD.status THEN RETURN NEW; END IF;
 IF OLD.status = 'submitted' AND NEW.status = 'in_review' THEN
  IF NOT EXISTS (SELECT 1 FROM claim_assignments a WHERE a.claim_id = NEW.id) THEN
   RAISE EXCEPTION 'Claim must be assigned before entering review';
  END IF;
 ELSIF OLD.status = 'in_review' AND NEW.status IN ('approved','rejected') THEN
  IF NOT EXISTS (
   SELECT 1 FROM claim_decisions d
   JOIN claim_assignments a ON a.claim_id = d.claim_id
   WHERE d.claim_id = NEW.id AND d.officer_id = a.officer_id
     AND d.verdict::text = NEW.status::text
  ) THEN
   RAISE EXCEPTION 'Final claim status requires a matching recorded decision';
  END IF;
 ELSE
  RAISE EXCEPTION 'Invalid claim status transition: % to %', OLD.status,NEW.status;
 END IF;
 NEW.updated_at = now();
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_repair_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Repair orders must be retained; cancel instead';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status <> 'open' OR NOT EXISTS (
   SELECT 1 FROM warranty_claims c JOIN claim_decisions d ON d.claim_id=c.id
   WHERE c.id=NEW.claim_id AND c.status='approved' AND d.verdict='approved'
  ) THEN
   RAISE EXCEPTION 'A repair must start open for an approved, decided claim';
  END IF;
 ELSE
  IF OLD.status IS DISTINCT FROM NEW.status THEN
   IF NOT (
    (OLD.status='open' AND NEW.status IN ('in_progress','cancelled')) OR
    (OLD.status='in_progress' AND NEW.status IN ('completed','cancelled'))
   ) THEN
    RAISE EXCEPTION 'Invalid repair order status transition: % to %',OLD.status,NEW.status;
   END IF;
   NEW.updated_at=now();
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.claim_id IS DISTINCT FROM OLD.claim_id
     OR NEW.opened_at IS DISTINCT FROM OLD.opened_at THEN
   RAISE EXCEPTION 'Repair order identity and claim are immutable';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.preserve_semantic_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='policy_documents' THEN
  IF (NEW.policy_id,NEW.original_text,NEW.sha256) IS DISTINCT FROM (OLD.policy_id,OLD.original_text,OLD.sha256)
     AND EXISTS(SELECT 1 FROM document_chunks WHERE document_id=OLD.id) THEN
   RAISE EXCEPTION 'Indexed policy document source is immutable';
  END IF;
 ELSE
  IF (NEW.document_id,NEW.chunk_number,NEW.content,NEW.embedding::text,NEW.metadata)
     IS DISTINCT FROM (OLD.document_id,OLD.chunk_number,OLD.content,OLD.embedding::text,OLD.metadata)
     AND EXISTS(SELECT 1 FROM semantic_matches WHERE chunk_id=OLD.id) THEN
   RAISE EXCEPTION 'Retrieved policy passage is immutable';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.prevent_history_rewrite()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='claim_decisions' THEN
  RAISE EXCEPTION 'Final claim decisions are immutable';
 ELSIF TG_TABLE_NAME='audit_events' THEN
  RAISE EXCEPTION 'Audit events are immutable';
 END IF;
 RAISE EXCEPTION 'History table mutation is not permitted';
END $function$

CREATE OR REPLACE FUNCTION public.validate_claim_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_owner uuid;
BEGIN
 SELECT rp.customer_id INTO actual_owner FROM warranties w
 JOIN registered_products rp ON rp.id = w.product_id WHERE w.id = NEW.warranty_id;
 IF actual_owner IS DISTINCT FROM NEW.customer_id THEN
  RAISE EXCEPTION 'Claim customer does not own the warranted product';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_registered_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM app_users WHERE id=NEW.customer_id AND role='customer' AND is_active) THEN
  RAISE EXCEPTION 'Registered product requires an active customer';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_warranty()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE owner_manufacturer uuid; policy_manufacturer uuid; purchase date;
        effective date; months integer;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.product_id,NEW.policy_id,NEW.start_date,NEW.end_date,NEW.created_at)
     IS DISTINCT FROM
     (OLD.id,OLD.product_id,OLD.policy_id,OLD.start_date,OLD.end_date,OLD.created_at)
     AND EXISTS(SELECT 1 FROM warranty_claims WHERE warranty_id=OLD.id) THEN
   RAISE EXCEPTION 'Claim warranty facts are immutable';
  END IF;
 END IF;
 SELECT pm.manufacturer_id,rp.purchased_on INTO owner_manufacturer,purchase
 FROM registered_products rp JOIN product_models pm ON pm.id=rp.model_id WHERE rp.id=NEW.product_id;
 SELECT manufacturer_id,effective_from,coverage_months INTO policy_manufacturer,effective,months
 FROM warranty_policies WHERE id=NEW.policy_id;
 IF owner_manufacturer IS DISTINCT FROM policy_manufacturer THEN
  RAISE EXCEPTION 'Warranty policy manufacturer differs from the product manufacturer';
 END IF;
 IF purchase<effective THEN RAISE EXCEPTION 'Policy was not effective on the purchase date'; END IF;
 IF NEW.start_date IS DISTINCT FROM purchase
    OR NEW.end_date IS DISTINCT FROM ((purchase+make_interval(months=>months))::date-1) THEN
  RAISE EXCEPTION 'Warranty dates must match the purchase and inclusive policy coverage';
 END IF;
 RETURN NEW;
END $function$
